CREATE TABLE suppliers (id TEXT PRIMARY KEY, name TEXT NOT NULL, country_code TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE destinations (id TEXT PRIMARY KEY, country_code TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE offers (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), destination_id TEXT NOT NULL REFERENCES destinations(id), type TEXT NOT NULL, name TEXT NOT NULL, status TEXT NOT NULL, source TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE bookings (id TEXT PRIMARY KEY, reference TEXT NOT NULL UNIQUE, secure_token TEXT NOT NULL UNIQUE, supplier_id TEXT NOT NULL, vehicle_id TEXT NOT NULL, customer_name TEXT NOT NULL, customer_email TEXT NOT NULL, customer_phone TEXT NOT NULL, pickup_date TEXT NOT NULL, return_date TEXT NOT NULL, pickup_location TEXT NOT NULL, currency TEXT NOT NULL, daily_rate_cents INTEGER NOT NULL CHECK(daily_rate_cents >= 0), total_cents INTEGER NOT NULL CHECK(total_cents >= 0), status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE booking_events (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), event_type TEXT NOT NULL, from_status TEXT, to_status TEXT NOT NULL, payload_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE audit_events (id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, source TEXT NOT NULL, metadata_json TEXT, created_at TEXT NOT NULL);
CREATE TABLE supplier_commercial_terms (id TEXT PRIMARY KEY, supplier_id TEXT NOT NULL REFERENCES suppliers(id), commission_bps INTEGER, currency TEXT, effective_from TEXT, effective_to TEXT, status TEXT NOT NULL, source TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE payment_routes (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), provider_id TEXT, status TEXT NOT NULL, decision_json TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE transactions (id TEXT PRIMARY KEY, booking_id TEXT NOT NULL REFERENCES bookings(id), provider_id TEXT, external_reference TEXT, amount_cents INTEGER NOT NULL, currency TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX idx_bookings_status ON bookings(status);
CREATE INDEX idx_booking_events_booking_id ON booking_events(booking_id);
CREATE INDEX idx_audit_events_entity ON audit_events(entity_type, entity_id);
